cssHead:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}
body {
  width: 390px;
  min-height: 844px;
  margin: 0 auto;
  background-color: #F9FAF7;
  color: #203E35;
  font-family: 'Geist', -apple-system, BlinkMacSystemFont, sans-serif;
  position: relative;
  display: flex;
  flex-direction: column;
}
.header {
  padding: 16px 20px 12px;
  position: sticky;
  top: 0;
  background-color: #F9FAF7;
  z-index: 20;
}
.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 36px;
  margin-bottom: 12px;
  position: relative;
}
.back-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  color: #203E35;
  background: transparent;
  border: none;
  cursor: pointer;
}
.sphere-logo {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #7DA490 0%, #4D7661 45%, #2B4E3E 85%, #183327 100%);
  box-shadow: 0 2px 6px rgba(32, 62, 53, 0.25), inset 0 1px 2px rgba(255, 255, 255, 0.4);
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}
.progress-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 8px;
}
.progress-segment {
  flex: 1;
  height: 4px;
  background-color: #E2E6DF;
  border-radius: 2px;
  overflow: hidden;
  position: relative;
}
.progress-fill {
  height: 100%;
  background-color: #D9A441;
  border-radius: 2px;
}
.header-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: #56654D;
  font-weight: 500;
}
.alertas-group {
  display: flex;
  align-items: center;
  gap: 4px;
}
.alert-dots {
  display: flex;
  gap: 3px;
  margin-left: 2px;
}
.alert-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: #A1312A;
}
.content {
  padding: 12px 20px 120px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.eyebrow {
  font-size: 12px;
  font-weight: 600;
  color: #8A6418;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  line-height: 1.35;
}
.headline {
  font-family: 'EB Garamond', serif;
  font-size: 28px;
  font-weight: 600;
  line-height: 1.15;
  color: #203E35;
  letter-spacing: -0.01em;
}
.body-text {
  font-size: 16px;
  line-height: 1.45;
  color: #56654D;
}
.card {
  background: #FFFFFF;
  border-radius: 16px;
  border: 1px solid #ECEEEA;
  box-shadow: 0 2px 8px rgba(32, 62, 53, 0.04);
  padding: 18px 16px;
}
.chart-container {
  width: 100%;
  background: #FFFFFF;
  border-radius: 16px;
  border: 1px solid #ECEEEA;
  box-shadow: 0 2px 8px rgba(32, 62, 53, 0.04);
  padding: 18px 16px 14px;
}
.chart-svg {
  width: 100%;
  height: 165px;
  display: block;
}
.chart-caption {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12px;
  color: #56654D;
  margin-top: 8px;
}
.stats-card {
  background: #FFFFFF;
  border-radius: 16px;
  border: 1px solid #ECEEEA;
  box-shadow: 0 2px 8px rgba(32, 62, 53, 0.04);
  padding: 4px 16px;
}
.stat-row {
  padding: 14px 0;
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.stat-row + .stat-row {
  border-top: 1px solid #F0F2ED;
}
.stat-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 5px;
  flex-shrink: 0;
}
.stat-content {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.stat-title {
  font-size: 15px;
  font-weight: 600;
  color: #203E35;
  line-height: 1.3;
}
.stat-desc {
  font-size: 14px;
  color: #56654D;
  line-height: 1.35;
}
.section-title {
  font-size: 17px;
  font-weight: 600;
  color: #203E35;
  margin-top: 4px;
}
.triad-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.triad-card {
  background: #FFFFFF;
  border-radius: 14px;
  border: 1px solid #ECEEEA;
  box-shadow: 0 1px 4px rgba(32, 62, 53, 0.03);
  padding: 14px 16px;
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.triad-icon-box {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: #F3F6F3;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #426B56;
  flex-shrink: 0;
}
.triad-body {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.triad-title {
  font-size: 15px;
  font-weight: 600;
  color: #203E35;
}
.triad-desc {
  font-size: 14px;
  color: #56654D;
  line-height: 1.4;
}
.conclusion-p {
  font-size: 16px;
  font-weight: 500;
  color: #203E35;
  line-height: 1.45;
}
.small-note {
  font-size: 13px;
  color: #56654D;
  line-height: 1.3;
  margin-top: -6px;
}
.bottom-cta-container {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 390px;
  padding: 16px 20px 24px;
  background: linear-gradient(180deg, rgba(249, 250, 247, 0) 0%, rgba(249, 250, 247, 0.95) 24%, #F9FAF7 100%);
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.primary-btn {
  width: 100%;
  height: 52px;
  background-color: #203E35;
  color: #FFFFFF;
  font-size: 16px;
  font-weight: 600;
  font-family: 'Geist', sans-serif;
  border: none;
  border-radius: 9999px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(32, 62, 53, 0.22);
  transition: background-color 0.15s ease, transform 0.1s ease;
}
.primary-btn:active {
  transform: scale(0.985);
  background-color: #183327;
}
